class PeriodicTask:
    def __init__(self, C, T, D):
        self.C = C
        self.T = T
        self.D = D

class AVRTask:
    def __init__(self, Theta, Phi, delta, modes):
        self.Theta = Theta
        self.Phi = Phi
        self.delta = delta # fraction for deadline
        self.modes = modes # list of (C_m, omega_m_upper_bound)

    def get_period(self, omega):
        return self.Theta / omega

    def get_deadline(self, omega):
        return self.delta * self.get_period(omega)

    def get_wcet(self, omega):
        # C_i(omega) is a non-increasing step function
        # Modes are sorted by omega_m_upper_bound in descending order
        for C_m, omega_m_upper_bound in sorted(self.modes, key=lambda x: x[1], reverse=True):
            if omega <= omega_m_upper_bound:
                return C_m
        return self.modes[-1][0] # Fallback to lowest speed mode WCET (omega_min)
